    52→static void Object_objectAddKey(void *prv, JSOBJ obj, JSOBJ name, JSOBJ value)
    53→{
    54→  int result = PyDict_SetItem(obj, name, value);
    55→  if (result == -1) {
    56→    // Clear the Python error state to prevent SystemError
    57→    PyErr_Clear();
    58→    // Set our own error
    59→    PyErr_SetString(JSONDecodeError, "Invalid JSON: object keys must be strings");
    60→  }
    61→  Py_DECREF( (PyObject *) name);
    62→  Py_DECREF( (PyObject *) value);
    63→  return;
    64→}
    65→
    66→static void Object_arrayAddItem(void *prv, JSOBJ obj, JSOBJ value)
    67→{
    68→  PyList_Append(obj, value);
    69→  Py_DECREF( (PyObject *) value);
    70→  return;
    71→}
