    73→/*
    74→Check that Py_UCS4 is the same as JSUINT32, else Object_newString will fail.
    75→Based on Linux's check in vbox_vmmdev_types.h.
    76→This should be replaced with
    77→  _Static_assert(sizeof(Py_UCS4) == sizeof(JSUINT32));
    78→when C11 is made mandatory (CPython 3.11+, PyPy ?).
    79→*/
    80→typedef char assert_py_ucs4_is_jsuint32[1 - 2*!(sizeof(Py_UCS4) == sizeof(JSUINT32))];
    81→
    82→static JSOBJ Object_newString(void *prv, JSUINT32 *start, JSUINT32 *end)
    83→{
    84→  return PyUnicode_FromKindAndData (PyUnicode_4BYTE_KIND, (Py_UCS4 *) start, (end - start));
    85→}
