   142→static JSOBJ Object_newIntegerFromString(void *prv, char *value, size_t length)
   143→{
   144→  // PyLong_FromString requires a NUL-terminated string in CPython, contrary to the documentation: https://github.com/python/cpython/issues/59200
   145→  char *buf = PyObject_Malloc(length + 1);
   146→  memcpy(buf, value, length);
   147→  buf[length] = '\0';
   148→  return PyLong_FromString(buf, NULL, 10);
   149→}
