   115→static char *PyUnicodeToUTF8Raw(JSOBJ _obj, size_t *_outLen, PyObject **pBytesObj)
   116→{
   117→  /*
   118→  Converts the PyUnicode object to char* whose size is stored in _outLen.
   119→  This conversion may require the creation of an intermediate PyBytes object.
   120→  In that case, the returned char* is in fact the internal buffer of that PyBytes object,
   121→  and when the char* buffer is no longer needed, the bytesObj must be DECREF'd.
   122→  */
   123→  PyObject *obj = (PyObject *) _obj;
   124→
   125→#ifndef Py_LIMITED_API
   126→  if (PyUnicode_IS_COMPACT_ASCII(obj))
   127→  {
   128→    Py_ssize_t len;
   129→    char *data = PyUnicode_AsUTF8AndSize(obj, &len);
   130→    *_outLen = len;
   131→    return data;
   132→  }
   133→#endif
   134→
   135→  PyObject *bytesObj = *pBytesObj = PyUnicode_AsEncodedString (obj, NULL, "surrogatepass");
   136→  if (!bytesObj)
   137→  {
   138→    return NULL;
   139→  }
   140→
   141→  *_outLen = PyBytes_GET_SIZE(bytesObj);
   142→  return PyBytes_AS_STRING(bytesObj);
   143→}
   144→
   145→static void *PyUnicodeToUTF8(JSOBJ _obj, JSONTypeContext *tc, void *outValue, size_t *_outLen)
   146→{
   147→  return PyUnicodeToUTF8Raw(_obj, _outLen, &(GET_TC(tc)->newObj));
