   242→static int Dict_iterNext(JSOBJ obj, JSONTypeContext *tc)
   243→{
   244→  PyObject* key;
   245→  if (!PyDict_Next(GET_TC(tc)->dictObj, &GET_TC(tc)->index, &key, &GET_TC(tc)->itemValue))
   246→  {
   247→    PRINTMARK();
   248→    return 0;
   249→  }
   250→  Py_XDECREF(GET_TC(tc)->itemName);
   251→  GET_TC(tc)->itemName = Dict_convertKey(key);
   252→  if (!GET_TC(tc)->itemName)
   253→  {
   254→    return -1;
   255→  }
   256→  PRINTMARK();
   257→  return 1;
   258→}
