   866→PyObject* objToJSONFile(PyObject* self, PyObject *args, PyObject *kwargs)
   867→{
   868→  PyObject *data;
   869→  PyObject *file;
   870→  PyObject *string;
   871→  PyObject *write;
   872→  PyObject *argtuple;
   873→  PyObject *write_result;
   874→
   875→  PRINTMARK();
   876→
   877→  if (!PyArg_ParseTuple (args, "OO", &data, &file))
   878→  {
   879→    return NULL;
   880→  }
   881→
   882→  if (!PyObject_HasAttrString (file, "write"))
   883→  {
   884→    PyErr_Format (PyExc_TypeError, "expected file");
   885→    return NULL;
   886→  }
   887→
   888→  write = PyObject_GetAttrString (file, "write");
   889→
   890→  if (!PyCallable_Check (write))
   891→  {
   892→    Py_XDECREF(write);
   893→    PyErr_Format (PyExc_TypeError, "expected file");
   894→    return NULL;
   895→  }
   896→
   897→  argtuple = PyTuple_Pack(1, data);
   898→
   899→  string = objToJSON (self, argtuple, kwargs);
   900→
   901→  if (string == NULL)
   902→  {
   903→    Py_XDECREF(write);
   904→    Py_XDECREF(argtuple);
   905→    return NULL;
   906→  }
   907→
   908→  Py_XDECREF(argtuple);
   909→
   910→  argtuple = PyTuple_Pack (1, string);
   911→  if (argtuple == NULL)
   912→  {
   913→    Py_XDECREF(write);
   914→    return NULL;
   915→  }
   916→
   917→  write_result = PyObject_CallObject (write, argtuple);
   918→  if (write_result == NULL)
   919→  {
   920→    Py_XDECREF(write);
   921→    Py_XDECREF(argtuple);
   922→    return NULL;
   923→  }
   924→
   925→  Py_DECREF(write_result);
   926→  Py_XDECREF(write);
   927→  Py_DECREF(argtuple);
   928→  Py_XDECREF(string);
   929→
   930→  PRINTMARK();
   931→
