   311→static FASTCALL_ATTR void FASTCALL_MSVC SkipWhitespace(struct DecoderState *ds)
   312→{
   313→  char *offset = ds->start;
   314→
   315→  for (;;)
   316→  {
   317→    switch (*offset)
   318→    {
   319→      case ' ':
   320→      case '\t':
   321→      case '\r':
   322→      case '\n':
   323→        offset ++;
   324→        break;
   325→
   326→      default:
   327→        ds->start = offset;
   328→        return;
   329→    }
   330→  }
   331→}
