   183→static FASTCALL_ATTR INLINE_PREFIX void FASTCALL_MSVC Buffer_AppendShortHexUnchecked (char *outputOffset, unsigned short value)
   184→{
   185→  *(outputOffset++) = g_hexChars[(value & 0xf000) >> 12];
   186→  *(outputOffset++) = g_hexChars[(value & 0x0f00) >> 8];
   187→  *(outputOffset++) = g_hexChars[(value & 0x00f0) >> 4];
   188→  *(outputOffset++) = g_hexChars[(value & 0x000f) >> 0];
   189→}
