   953→char *JSON_EncodeObject(JSOBJ obj, JSONObjectEncoder *enc, char *_buffer, size_t _cbBuffer, size_t *_outLen)
   954→{
   955→  enc->malloc = enc->malloc ? enc->malloc : malloc;
   956→  enc->free =  enc->free ? enc->free : free;
   957→  enc->realloc = enc->realloc ? enc->realloc : realloc;
   958→  enc->errorMsg = NULL;
   959→  enc->errorObj = NULL;
   960→  enc->level = 0;
   961→
   962→  if (enc->recursionMax < 1)
   963→  {
   964→    enc->recursionMax = JSON_MAX_RECURSION_DEPTH;
   965→  }
   966→
   967→  if (_buffer == NULL)
   968→  {
   969→    _cbBuffer = 32768;
   970→    enc->start = (char *) enc->malloc (_cbBuffer);
   971→    if (!enc->start)
   972→    {
   973→      SetError(obj, enc, "Could not reserve memory block");
   974→      return NULL;
   975→    }
   976→    enc->heap = 1;
   977→  }
   978→  else
   979→  {
   980→    enc->start = _buffer;
   981→    enc->heap = 0;
   982→  }
   983→
   984→  enc->end = enc->start + _cbBuffer;
   985→  enc->offset = enc->start;
   986→
   987→  encode (obj, enc, NULL, 0);
   988→
   989→  if (enc->errorMsg)
   990→  {
   991→    if (enc->heap == 1)
   992→    {
   993→      // Buffer was realloc'd at some point, or no initial buffer was provided.
   994→      enc->free(enc->start);
   995→    }
   996→    return NULL;
   997→  }
   998→
   999→  *_outLen = enc->offset - enc->start;
  1000→  return enc->start;
  1001→}
